SELECT c.course_name, c.course_id
FROM Courses AS c
WHERE (SELECT COUNT(*) FROM Sections AS s WHERE s.course_id = c.course_id) < 2;

SELECT p.Name
FROM people AS p
JOIN poker_player AS pp ON pp.People_ID = p.People_ID;

SELECT p.first_name, p.last_name
FROM people AS p
JOIN poker_player AS pp ON pp.People_ID = p.People_ID;

SELECT c.Name, o.Orchestra
FROM conductor AS c
JOIN orchestra AS o ON o.Conductor_ID = c.Conductor_ID;

SELECT first_name, birthyear, bithday
FROM players
WHERE country_code = 'USA';

SELECT t.date_of_treatment, p.first_name
FROM Treatments AS t
JOIN Professionals AS p ON p.professional_id = t.professional_id;

SELECT t.date_of_treatment, p.first_name
FROM Treatments AS t
JOIN Professionals AS p ON p.professional_id = t.professional_id;

SELECT contestant_number, contestant_name
FROM CONTESTANTS
ORDER BY contestant_name DESC;

SELECT contestant_number, first_name, last_name
FROM CONTESTANTS
ORDER BY last_name DESC, first_name DESC;

SELECT first_name, birth_date
FROM players
WHERE country_code = 'USA';

SELECT student_id, COUNT(*) AS number_of_likes
FROM Likes
GROUP BY student_id;
